{"query": "
-- Verify how to identify "former" employees — salary records for truly departed employees
-- A former employee has NO salary record with to_date = '9999-01-01'
SELECT COUNT(DISTINCT s.employee_id) AS former_only
FROM employees.salary s
WHERE s.employee_id NOT IN (
  SELECT DISTINCT employee_id FROM employees.salary WHERE to_date = '9999-01-01'
);
"}
